#define main original_main
#include "../sort-cuda/main.cu"
#undef main
struct Case{int n;std::vector<unsigned>input,want;unsigned*a,*b,*sums;};
static std::vector<unsigned>oracle(const std::vector<unsigned>&input){auto sorted=input;std::sort(sorted.begin(),sorted.end());auto scratch=sorted;std::stable_sort(scratch.begin(),scratch.end(),[](unsigned a,unsigned b){return (a&0x0fffffffu)<(b&0x0fffffffu);});std::vector<unsigned>counts(1024),offsets;int n=input.size(),region=(n/4)/64*4;for(int group=0;group<64;++group){int start=group*region,stop=group==63?n:start+region;for(int i=start;i<stop;++i)++counts[(scratch[i]>>28)*64+group];}unsigned seed=0;for(auto count:counts){offsets.push_back(seed);seed+=count;}sorted.insert(sorted.end(),scratch.begin(),scratch.end());sorted.insert(sorted.end(),offsets.begin(),offsets.end());return sorted;}
static void run(Case&c){for(unsigned shift=0;shift<32;shift+=4){auto input=(shift/4)%2==0?c.a:c.b,output=(shift/4)%2==0?c.b:c.a;reduce<<<64,256>>>(input,c.sums,c.n,shift);top_scan<<<1,256>>>(c.sums,64);bottom_scan<<<64,256>>>(output,input,c.sums,c.n,shift);}}
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
int main(){std::vector<Case>cases;std::vector<unsigned>prefix;for(int n:{4096,65540}){Case c;c.n=n;c.input.resize(n);for(unsigned i=0;i<unsigned(n);++i)c.input[i]=n==4096?i%16:i%17==0?0xffffffffu:i%19==0?0u:(i*2654435761u)^((i>>3)*2246822519u);c.want=oracle(c.input);prefix.insert(prefix.end(),c.input.begin(),c.input.end());prefix.push_back(n);prefix.push_back(64);prefix.push_back(3);ck(cudaMalloc(&c.a,n*4));ck(cudaMalloc(&c.b,n*4));ck(cudaMalloc(&c.sums,1024*4));cases.push_back(c);}auto trial=[&](Case&c,std::vector<unsigned>&got){ck(cudaMemcpy(c.a,c.input.data(),c.n*4,cudaMemcpyHostToDevice));ck(cudaMemset(c.b,0,c.n*4));ck(cudaMemset(c.sums,0,1024*4));ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();for(int k=0;k<3;++k)run(c);ck(cudaDeviceSynchronize());double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/3;got.resize(2*c.n+1024);ck(cudaMemcpy(got.data(),c.a,c.n*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+c.n,c.b,c.n*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(got.data()+2*c.n,c.sums,1024*4,cudaMemcpyDeviceToHost));return elapsed;};for(auto&c:cases){std::vector<unsigned>unused;trial(c,unused);}for(int tr=1;tr<=5;++tr){std::vector<unsigned>out=prefix;bool ok=true;double elapsed=0;for(auto&c:cases){std::vector<unsigned>got;elapsed+=trial(c,got);ok&=got==c.want;out.insert(out.end(),got.begin(),got.end());}std::string path="trial_"+std::to_string(tr)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":210962,\"max_abs_error\":0,\"timing_region\":\"sum_two_cases_three_full_radix_pass_means\",\"jit_excluded\":true,\"internal_repeats\":3,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":210962,\"byte_order\":\"little\"}}\n",tr,elapsed,ok?"true":"false",path.c_str());if(!ok)return 3;}for(auto&c:cases){cudaFree(c.a);cudaFree(c.b);cudaFree(c.sums);}return 0;}
